using System.Text.Json;
using Grpc.Core;
using Microsoft.Extensions.Caching.Distributed;
using TrailRent.Catalog.Grpc;
using TrailRent.Orders.Grpc;
using TrailRent.Reviews.Grpc;
var b=WebApplication.CreateBuilder(args);b.Services.AddDistributedMemoryCache();b.Services.AddGrpcClient<OrdersService.OrdersServiceClient>(o=>o.Address=new Uri("https://orders-api"));b.Services.AddGrpcClient<CatalogService.CatalogServiceClient>(o=>o.Address=new Uri("https://catalog-api"));b.Services.AddGrpcClient<ReviewsService.ReviewsServiceClient>(o=>o.Address=new Uri("https://reviews-api"));var a=b.Build();a.MapGet("/api/aggregator/orders/{id:long}/full",async(long id,OrdersService.OrdersServiceClient orders,CatalogService.CatalogServiceClient catalog,ReviewsService.ReviewsServiceClient reviews,IDistributedCache cache,ILogger<Program> log,CancellationToken ct)=>{var key=$"aggregator:order:{id}:full";var hit=await cache.GetAsync(key,ct);if(hit is not null)return Results.Ok(JsonSerializer.Deserialize<object>(hit));var order=await orders.GetOrderAsync(new(){Id=id},cancellationToken:ct).ResponseAsync;var ids=order.Items.Select(x=>x.ProductId).ToArray();var warnings=new List<string>();async Task<T?> Safe<T>(Func<Task<T>> f,string s){try{return await f();}catch(RpcException ex)when(ex.StatusCode is StatusCode.Unavailable or StatusCode.DeadlineExceeded){warnings.Add($"{s} is unavailable");log.LogWarning(ex,"gRPC {Service} unavailable",s);return default;}}var products=Safe(()=>catalog.GetProductsByIdsAsync(new(){Ids={ids}},cancellationToken:ct).ResponseAsync,"catalog-api");var review=Safe(()=>reviews.GetForProductsAsync(new(){ProductIds={ids}},cancellationToken:ct).ResponseAsync,"reviews-api");await Task.WhenAll(products,review);var result=new{order,products=await products,reviews=await review,warnings};if(warnings.Count==0)await cache.SetAsync(key,JsonSerializer.SerializeToUtf8Bytes(result),new DistributedCacheEntryOptions{AbsoluteExpirationRelativeToNow=TimeSpan.FromSeconds(30)},ct);return Results.Ok(result);});a.Run();public partial class Program;
